/** The payout is limited to what remains of the policy's cap. */
const claimResult = (
  step: ClaimStep,
  policy: QuoteStep,
  capRemaining: number,
): ClaimResult => {
  const payout = Math.min(incidentPayout(step.incident, policy.items), capRemaining);

  return { payout, remainingCap: capRemaining - payout };
};

/**
 * Steps are processed in order: a claim draws on what earlier claims left of
 * its policy's cap.
 */
export const runScenario = (scenario: Scenario): ScenarioResults => {
  const capRemaining = new Map<number, number>();
  const results: (QuoteResult | ClaimResult)[] = [];

  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push({
        premium: quotePremium(
          step,
          scenario.customer,
          isFollowUpContract(scenario.steps.slice(0, index)),
        ),
      });
      capRemaining.set(index, policyCap(step));

      return;
    }

    const policy = scenario.steps[step.policy] as QuoteStep;
    const result = claimResult(step, policy, capRemaining.get(step.policy) as number);

    capRemaining.set(step.policy, result.remainingCap);
    results.push(result);
  });

  return { results };
};

